function RichArea({ label, value, onChange, placeholder }) {
  const taRef = useRef(null);
  const wrapBold = () => {
    const ta = taRef.current;
    if (!ta) return;
    const start = ta.selectionStart;
    const end = ta.selectionEnd;
    const before = value.slice(0, start);
    const selected = value.slice(start, end) || "굵게";
    const after = value.slice(end);
    const next = `${before}**${selected}**${after}`;
    onChange(next);
    requestAnimationFrame(() => {
      ta.focus();
      const cursor = start + 2 + selected.length + 2;
      ta.setSelectionRange(cursor, cursor);
    });
  };
  return (
    <div style={{ marginBottom: 16 }}>
      <div style={{ display: "flex", alignItems: "center", justifyContent: "space-between", margin: "0 0 8px 4px" }}>
        {label && <div style={{ fontFamily: FONT_SANS, fontSize: 12, fontWeight: 500, color: C.inkSoft }}>{label}</div>}
        <button type="button" onClick={wrapBold} title="선택한 글자를 굵게" style={{ display: "flex", alignItems: "center", gap: 4, background: C.fieldBg, border: "none", borderRadius: 8, padding: "5px 9px", cursor: "pointer", color: C.inkSoft, fontFamily: FONT_SANS, fontSize: 12 }}>
          <Bold size={12} /> 굵게
        </button>
      </div>
      <textarea ref={taRef} value={value} onChange={(e) => onChange(e.target.value)} placeholder={placeholder} style={{ width: "100%", fontFamily: FONT_SANS, fontSize: 15, color: C.ink, background: C.fieldBg, border: "none", borderRadius: 18, padding: "13px 18px", boxSizing: "border-box", outline: "none", resize: "vertical", minHeight: 80 }} />
      <div style={{ fontFamily: FONT_SANS, fontSize: 11, color: C.inkFaint, marginTop: 4, marginLeft: 4 }}>글자를 선택하고 "굵게"를 누르거나, 직접 **이렇게** 감싸면 굵게 표시돼요.</div>
    </div>
  );
}

function ProgressBar({ value, tone = "blue" }) {
  const fill = tone === "blue" ? "#4E7FEF" : tone === "green" ? C.correct : "#EA8C4B";
  return (
    <div style={{ height: 6, borderRadius: 999, background: C.fieldBg, overflow: "hidden" }}>
      <div style={{ height: "100%", width: `${Math.round(value * 100)}%`, background: fill, borderRadius: 999, transition: "width 0.3s ease" }} />
    </div>
  );
}

function PhotoPicker({ photo, onChange, onRemove }) {
  const inputRef = useRef(null);
  const [error, setError] = useState("");
  const handleFile = async (e) => {
    const file = e.target.files && e.target.files[0];
    if (!file) return;
    if (!file.type.startsWith("image/")) {
      setError("이미지 파일만 첨부할 수 있습니다.");
      return;
    }
    try {
      const dataUrl = await compressImage(file);
      setError("");
      onChange(dataUrl);
    } catch (err) {
      setError("이미지를 처리하지 못했습니다. 다시 시도해 주세요.");
    }
  };
  return (
    <div style={{ marginBottom: 16 }}>
      <div style={{ fontFamily: FONT_SANS, fontSize: 12, fontWeight: 500, color: C.inkSoft, margin: "0 0 8px 4px" }}>사진 (선택)</div>
      {photo ? (
        <div style={{ position: "relative", display: "inline-block" }}>
          <img src={photo} alt="첨부 사진" style={{ maxWidth: 220, maxHeight: 160, display: "block", borderRadius: 16 }} />
          <button onClick={onRemove} aria-label="사진 삭제" style={{ position: "absolute", top: 8, right: 8, width: 26, height: 26, borderRadius: "50%", border: "none", background: "rgba(23,23,26,0.72)", color: "#fff", display: "flex", alignItems: "center", justifyContent: "center", cursor: "pointer" }}>
            <X size={14} />
          </button>
        </div>
      ) : (
        <button type="button" onClick={() => inputRef.current && inputRef.current.click()} style={{ display: "flex", alignItems: "center", gap: 8, fontFamily: FONT_SANS, fontSize: 14, color: C.inkSoft, background: C.fieldBg, border: "none", borderRadius: 16, padding: "14px 18px", cursor: "pointer" }}>
          <ImageIcon size={16} />
          사진 추가
        </button>
      )}
      {error && <div style={{ fontFamily: FONT_SANS, fontSize: 12, color: C.wrong, marginTop: 6 }}>{error}</div>}
      <input ref={inputRef} type="file" accept="image/*" onChange={handleFile} style={{ display: "none" }} />
    </div>
  );
}

