/* ----------------------------------------------------------------
   뒤집는 카드
----------------------------------------------------------------- */
function FlipCard({ front, back, flipped, onToggle, minHeight = 0 }) {
  const faceBase = { gridRow: 1, gridColumn: 1, backfaceVisibility: "hidden", WebkitBackfaceVisibility: "hidden", borderRadius: 20, background: C.card, boxShadow: C.shadow, padding: 22, boxSizing: "border-box" };
  return (
    <div onClick={onToggle} style={{ perspective: 1400, cursor: "pointer" }}>
      <div style={{ display: "grid", minHeight, transformStyle: "preserve-3d", transition: "transform 0.45s cubic-bezier(.4,.2,.2,1)", transform: flipped ? "rotateY(180deg)" : "rotateY(0deg)" }}>
        <div style={faceBase}>{front}</div>
        <div style={{ ...faceBase, transform: "rotateY(180deg)" }}>{back}</div>
      </div>
    </div>
  );
}

function cardFaces(card) {
  const isRanking = card.type === "ranking";
  const front = (
    <div>
      <span style={{ fontFamily: FONT_SANS, fontSize: 11, color: C.inkFaint, background: C.fieldBg, padding: "3px 9px", borderRadius: 999 }}>{isRanking ? "순위형" : "자유형"}</span>
      <h3 style={{ fontFamily: FONT_SERIF, fontWeight: 500, fontSize: 19, color: C.ink, margin: "12px 0 6px" }}>{renderRich(isRanking ? card.title : card.question)}</h3>
      {card.photo && <img src={card.photo} alt="" style={{ maxWidth: "100%", maxHeight: 140, borderRadius: 12, marginTop: 8 }} />}
      <p style={{ fontFamily: FONT_SANS, fontSize: 12, color: C.inkFaint, marginTop: 10 }}>탭해서 {isRanking ? "순서 확인" : "답 보기"}</p>
    </div>
  );
  const back = isRanking ? (
    <div>
      {card.items.map((it, i) => (
        <div key={i} style={{ display: "flex", alignItems: "center", gap: 10, padding: "5px 0" }}>
          <Orb hue="orange" letter={i + 1} size={24} />
          <span style={{ fontFamily: FONT_SANS, fontSize: 15, color: C.ink }}>{renderRich(it)}</span>
        </div>
      ))}
    </div>
  ) : (
    <p style={{ fontFamily: FONT_SANS, fontSize: 15, color: C.ink, lineHeight: 1.6, margin: 0 }}>{renderRich(card.answer)}</p>
  );
  return { front, back };
}

/* ----------------------------------------------------------------
   화면: 카드 학습
----------------------------------------------------------------- */
function StudyScreen({ folderName, cards, onlyFavorites, onExit, onToggleFavorite }) {
  const [order, setOrder] = useState(() => cards.map((_, i) => i));
  const [index, setIndex] = useState(0);
  const [flipped, setFlipped] = useState(false);

  useEffect(() => {
    setOrder(cards.map((_, i) => i));
    setIndex(0);
    setFlipped(false);
  }, [cards.length]);

  if (cards.length === 0) {
    return (
      <div>
        <BackRow onBack={onExit} label="폴더로" />
        <Card style={{ padding: "40px 24px", textAlign: "center" }}>
          <p style={{ fontFamily: FONT_SANS, fontSize: 14, color: C.inkFaint, margin: 0 }}>
            {onlyFavorites ? "별표한 카드가 아직 없습니다." : "이 폴더에는 아직 카드가 없습니다."}
          </p>
        </Card>
      </div>
    );
  }

  const safeIndex = Math.min(index, order.length - 1);
  const card = cards[order[safeIndex]];
  const { front, back } = cardFaces(card);
  const go = (delta) => {
    setFlipped(false);
    setIndex((i) => Math.max(0, Math.min(order.length - 1, i + delta)));
  };
  const reshuffle = () => {
    setOrder(shuffle(cards.map((_, i) => i)));
    setIndex(0);
    setFlipped(false);
  };

  return (
    <div style={{ maxWidth: 480, margin: "0 auto" }}>
      <div style={{ display: "flex", alignItems: "center", justifyContent: "space-between", marginBottom: 16 }}>
        <BackRow onBack={onExit} label="폴더로" />
        <div style={{ display: "flex", gap: 6 }}>
          <RoundIconButton title={card.favorite ? "다시보기 해제" : "다시보기로 표시"} tone={card.favorite ? "star" : "default"} onClick={() => onToggleFavorite(card.id)}>
            <Star size={15} fill={card.favorite ? C.star : "none"} />
          </RoundIconButton>
          <RoundIconButton title="순서 섞기" onClick={reshuffle}>
            <Shuffle size={15} />
          </RoundIconButton>
        </div>
      </div>
      <p style={{ fontFamily: FONT_SANS, fontSize: 12, color: C.inkFaint, margin: "0 0 6px" }}>
        {onlyFavorites ? "⭐ 별표 모음 · " : ""}{folderName} · {safeIndex + 1} / {order.length}
      </p>
      <FlipCard front={front} back={back} flipped={flipped} onToggle={() => setFlipped((f) => !f)} minHeight={260} />
      <div style={{ display: "flex", gap: 10, marginTop: 18 }}>
        <PillButton tone="secondary" onClick={() => go(-1)} style={{ flex: 1, opacity: safeIndex === 0 ? 0.4 : 1 }}>
          <ChevronLeft size={16} /> 이전
        </PillButton>
        <PillButton onClick={() => go(1)} style={{ flex: 1, opacity: safeIndex === order.length - 1 ? 0.4 : 1 }}>
          다음 <ChevronRight size={16} />
        </PillButton>
      </div>
    </div>
  );
}

/* ----------------------------------------------------------------
   화면: 백업
----------------------------------------------------------------- */
function BackupScreen({ folders, cardsByFolder, onBack, onImport, user, onSignOut, hasLegacyData, onImportLegacy }) {
  const fileRef = useRef(null);
  const [status, setStatus] = useState("");
  const [jsonText, setJsonText] = useState("");
  const [legacyStatus, setLegacyStatus] = useState("");

  const runLegacyImport = async () => {
    setLegacyStatus("가져오는 중…");
    const result = await onImportLegacy();
    setLegacyStatus(`이 기기에 있던 데이터를 가져왔어요 (${result.migrated}개). 새로고침해서 확인해 보세요.`);
  };

  const doExport = () => {
    const payload = { version: 1, exportedAt: Date.now(), folders, cardsByFolder };
    const text = JSON.stringify(payload, null, 2);
    setJsonText(text);
    try {
      const blob = new Blob([text], { type: "application/json" });
      const url = URL.createObjectURL(blob);
      const a = document.createElement("a");
      a.href = url;
      a.download = `geo-memo-backup-${new Date().toISOString().slice(0, 10)}.json`;
      document.body.appendChild(a);
      a.click();
      document.body.removeChild(a);
      URL.revokeObjectURL(url);
      setStatus("다운로드를 시도했어요. 안 됐다면 아래 텍스트를 복사해서 파일로 저장해 두세요.");
    } catch (e) {
      setStatus("자동 다운로드가 막혀 있어요. 아래 텍스트를 전체 복사해서 .json 파일로 저장해 두세요.");
    }
  };

  const copyText = async () => {
    try {
      await navigator.clipboard.writeText(jsonText);
      setStatus("클립보드에 복사했어요.");
    } catch (e) {
      setStatus("복사가 막혀 있어요. 아래 상자를 눌러 전체 선택한 뒤 직접 복사해 주세요.");
    }
  };

  const handleFile = (e) => {
    const file = e.target.files && e.target.files[0];
    if (!file) return;
    const reader = new FileReader();
    reader.onload = (ev) => {
      try {
        const payload = JSON.parse(ev.target.result);
        if (!payload.folders || !payload.cardsByFolder) throw new Error("invalid");
        onImport(payload);
        setStatus(`불러왔어요. 폴더 ${payload.folders.length}개.`);
      } catch (err) {
        setStatus("이 파일을 읽지 못했어요. 이 앱에서 내보낸 백업 파일이 맞는지 확인해 주세요.");
      }
    };
    reader.readAsText(file);
  };

  return (
    <div>
      <BackRow onBack={onBack} label="홈으로" />
      <h1 style={{ fontFamily: FONT_SERIF, fontWeight: 500, fontSize: 34, letterSpacing: "-0.015em", color: C.ink, margin: "0 0 8px" }}>백업</h1>
      <p style={{ fontFamily: FONT_SANS, fontSize: 13, color: C.inkSoft, margin: "0 0 22px" }}>폴더와 카드 전체를 파일 하나로 내보내거나, 예전 백업 파일을 불러올 수 있어요.</p>

      <div style={{ display: "flex", flexDirection: "column", gap: 10, marginBottom: 20 }}>
        <ActionRow hue="blue" icon={Download} title="백업 내보내기" subtitle={`폴더 ${folders.length}개를 파일로 저장`} onClick={doExport} />
        <ActionRow hue="orange" icon={Upload} title="백업 불러오기" subtitle="현재 데이터를 파일 내용으로 대체" onClick={() => fileRef.current && fileRef.current.click()} />
      </div>
      <input ref={fileRef} type="file" accept="application/json" onChange={handleFile} style={{ display: "none" }} />

      {status && (
        <Card style={{ padding: 14, marginBottom: 14 }}>
          <p style={{ fontFamily: FONT_SANS, fontSize: 13, color: C.inkSoft, margin: 0 }}>{status}</p>
        </Card>
      )}

      {jsonText && (
        <div>
          <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", margin: "0 0 8px 4px" }}>
            <span style={{ fontFamily: FONT_SANS, fontSize: 12, fontWeight: 500, color: C.inkSoft }}>백업 내용 (복사용)</span>
            <PillButton tone="secondary" onClick={copyText} style={{ padding: "6px 12px", fontSize: 12 }}>전체 복사</PillButton>
          </div>
          <textarea
            readOnly
            value={jsonText}
            onFocus={(e) => e.target.select()}
            style={{ width: "100%", height: 160, fontFamily: "monospace", fontSize: 11, color: C.inkSoft, background: C.fieldBg, border: "none", borderRadius: 16, padding: 14, boxSizing: "border-box", resize: "vertical" }}
          />
        </div>
      )}

      {hasLegacyData && (
        <Card style={{ padding: 18, marginTop: 20, background: "#FBEEDF" }}>
          <p style={{ fontFamily: FONT_SANS, fontSize: 13, fontWeight: 500, color: C.ink, margin: "0 0 4px" }}>이 기기에 로그인 전 데이터가 남아있어요</p>
          <p style={{ fontFamily: FONT_SANS, fontSize: 12.5, color: C.inkSoft, margin: "0 0 12px" }}>계정에 이미 있는 항목은 덮어쓰지 않고, 없는 것만 가져와요.</p>
          <PillButton onClick={runLegacyImport}>이 기기 데이터 가져오기</PillButton>
          {legacyStatus && <p style={{ fontFamily: FONT_SANS, fontSize: 12, color: C.inkSoft, margin: "10px 0 0" }}>{legacyStatus}</p>}
        </Card>
      )}

      {user && (
        <div style={{ marginTop: 20, display: "flex", alignItems: "center", justifyContent: "space-between", gap: 12 }}>
          <div style={{ fontFamily: FONT_SANS, fontSize: 12.5, color: C.inkSoft, overflow: "hidden", textOverflow: "ellipsis", whiteSpace: "nowrap" }}>
            {user.email} 계정으로 로그인됨
          </div>
          <PillButton tone="secondary" onClick={onSignOut} style={{ flexShrink: 0 }}>로그아웃</PillButton>
        </div>
      )}
    </div>
  );
}

/* ----------------------------------------------------------------
   화면: 통계
----------------------------------------------------------------- */
function StatsScreen({ folders, cardsByFolder, onBack, wide }) {
  const rows = folders.map((f) => {
    const cards = cardsByFolder[f.id] || [];
    const totalReview = cards.reduce((s, c) => s + (c.reviewCount || 0), 0);
    const totalCorrect = cards.reduce((s, c) => s + (c.correctCount || 0), 0);
    const accuracy = totalReview > 0 ? Math.round((totalCorrect / totalReview) * 100) : null;
    return { folder: f, cardCount: cards.length, accuracy, totalReview };
  });
  const reviewed = rows.filter((r) => r.accuracy !== null).sort((a, b) => a.accuracy - b.accuracy);
  const totalCards = rows.reduce((s, r) => s + r.cardCount, 0);
  const subjectMeta = SUBJECTS.find((s) => s.id === (folders[0] && folders[0].subject));

  return (
    <div>
      <BackRow onBack={onBack} label="홈으로" />
      <h1 style={{ fontFamily: FONT_SERIF, fontWeight: 500, fontSize: 34, letterSpacing: "-0.015em", color: C.ink, margin: "0 0 8px" }}>통계</h1>
      <p style={{ fontFamily: FONT_SANS, fontSize: 13, color: C.inkSoft, margin: "0 0 20px" }}>전체 {totalCards}개 카드 · {folders.length}개 폴더</p>

      {reviewed.length === 0 ? (
        <Card style={{ padding: "40px 24px", textAlign: "center" }}>
          <p style={{ fontFamily: FONT_SANS, fontSize: 14, color: C.inkFaint, margin: 0 }}>아직 퀴즈 기록이 없어요. 퀴즈를 풀면 여기에 정답률이 쌓여요.</p>
        </Card>
      ) : (
        <div>
          <div style={{ fontFamily: FONT_SANS, fontSize: 12, fontWeight: 500, color: C.inkSoft, margin: "0 0 8px 4px" }}>정답률이 낮은 폴더부터</div>
          <div style={{ display: "grid", gridTemplateColumns: wide ? "1fr 1fr" : "1fr", gap: 10 }}>
            {reviewed.map((r) => (
              <Card key={r.folder.id} style={{ padding: "14px 16px" }}>
                <div style={{ display: "flex", alignItems: "center", justifyContent: "space-between", marginBottom: 8 }}>
                  <div style={{ display: "flex", alignItems: "center", gap: 10 }}>
                    <Orb hue="blue" emoji={r.folder.emoji} letter={r.folder.name.slice(0, 1)} size={32} />
                    <span style={{ fontFamily: FONT_SERIF, fontSize: 15, color: C.ink }}>{r.folder.name}</span>
                  </div>
                  <span style={{ fontFamily: FONT_SANS, fontSize: 14, fontWeight: 500, color: r.accuracy >= 70 ? C.correct : C.wrong }}>{r.accuracy}%</span>
                </div>
                <ProgressBar value={r.accuracy / 100} tone={r.accuracy >= 70 ? "green" : "orange"} />
              </Card>
            ))}
          </div>
        </div>
      )}
    </div>
  );
}

/* ----------------------------------------------------------------
   화면: 검색
----------------------------------------------------------------- */
function SearchScreen({ folders, cardsByFolder, onBack, onOpenCard }) {
  const [query, setQuery] = useState("");
  const q = query.trim().toLowerCase();

  const results = [];
  if (q) {
    folders.forEach((f) => {
      (cardsByFolder[f.id] || []).forEach((c) => {
        const haystack = c.type === "ranking" ? [c.title, ...(c.items || [])] : [c.question, c.answer];
        const text = stripMd(haystack.join(" ")).toLowerCase();
        if (text.includes(q)) results.push({ folder: f, card: c });
      });
    });
  }

  return (
    <div>
      <BackRow onBack={onBack} label="홈으로" />
      <h1 style={{ fontFamily: FONT_SERIF, fontWeight: 500, fontSize: 34, letterSpacing: "-0.015em", color: C.ink, margin: "0 0 18px" }}>검색</h1>
      <input
        autoFocus
        value={query}
        onChange={(e) => setQuery(e.target.value)}
        placeholder="폴더, 카드 내용 검색"
        style={{ width: "100%", fontFamily: FONT_SANS, fontSize: 15, color: C.ink, background: C.fieldBg, border: "none", borderRadius: 999, padding: "13px 18px", boxSizing: "border-box", outline: "none", marginBottom: 18 }}
      />
      {q && (
        <p style={{ fontFamily: FONT_SANS, fontSize: 12, color: C.inkFaint, margin: "0 0 10px 4px" }}>{results.length}개 결과</p>
      )}
      <div style={{ display: "flex", flexDirection: "column", gap: 10 }}>
        {results.map(({ folder, card }) => {
          const isRanking = card.type === "ranking";
          return (
            <Card key={card.id} onClick={() => onOpenCard(folder.subject, folder.id, card.id)} style={{ padding: "14px 16px", display: "flex", alignItems: "center", gap: 14 }}>
              <Orb hue={isRanking ? "orange" : "blue"} icon={isRanking ? ListOrdered : HelpCircle} size={40} />
              <div style={{ minWidth: 0 }}>
                <div style={{ fontFamily: FONT_SANS, fontSize: 15, color: C.ink, whiteSpace: "nowrap", overflow: "hidden", textOverflow: "ellipsis" }}>{renderRich(isRanking ? card.title : card.question)}</div>
                <div style={{ fontFamily: FONT_SANS, fontSize: 12, color: C.inkFaint, marginTop: 2 }}>{folder.name}</div>
              </div>
            </Card>
          );
        })}
      </div>
    </div>
  );
}

/* ----------------------------------------------------------------
   지도 필기 — 링크 삽입용 과목 > 폴더 > 카드 선택 모달
----------------------------------------------------------------- */
